export const meExportDataResponseConsentHistoryItemGrantedAtRegExp = new RegExp('^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z))$');


export const MeExportDataResponse = zod.object({
  "exportedAt": zod.iso.datetime({"offset":true}).regex(meExportDataResponseExportedAtRegExp),
  "profile": zod.object({
  "id": zod.uuid().regex(meExportDataResponseProfileIdRegExp),
  "email": zod.string(),
  "fullName": zod.string(),
  "phone": zod.string().nullable(),
  "birthDate": zod.iso.date().regex(meExportDataResponseProfileBirthDateRegExp).nullable(),
  "locale": zod.string(),
  "isEmailVerified": zod.boolean(),
  "createdAt": zod.iso.datetime({"offset":true}).regex(meExportDataResponseProfileCreatedAtRegExp)
}),
  "memberships": zod.array(zod.object({
  "membershipId": zod.uuid().regex(meExportDataResponseMembershipsItemMembershipIdRegExp),
  "centerId": zod.uuid().regex(meExportDataResponseMembershipsItemCenterIdRegExp),
  "role": zod.enum(['owner', 'admin', 'staff', 'client']),
  "status": zod.enum(['invited', 'active', 'blocked', 'left']),
  "joinedAt": zod.iso.datetime({"offset":true}).regex(meExportDataResponseMembershipsItemJoinedAtRegExp),
  "center": zod.object({
  "name": zod.string(),
  "slug": zod.string(),
  "sectorId": zod.string(),
  "brandColor": zod.string(),
  "logoUrl": zod.string().nullable()
})
})),
  "consentHistory": zod.array(zod.object({
  "kind": zod.enum(['privacy', 'terms', 'marketing', 'health', 'image', 'parental']),
  "version": zod.string(),
  "isGranted": zod.boolean(),
  "grantedAt": zod.iso.datetime({"offset":true}).regex(meExportDataResponseConsentHistoryItemGrantedAtRegExp)
}))
})

/**
 * @summary Registra este móvil para recibir avisos push. Si el token ya era de otra cuenta (otra persona usó antes el móvil), pasa a esta.
 */
export const meRegisterPushDeviceBodyTokenRegExp = new RegExp('^Expo(?:nent)?PushToken\\[[A-Za-z0-9_-]{10,200}\\]$');


export const MeRegisterPushDeviceBody = zod.object({
  "token": zod.string().regex(meRegisterPushDeviceBodyTokenRegExp),
  "platform": zod.enum(['ios', 'android'])
})

export const MeRegisterPushDeviceResponse = zod.void()

/**
 * @summary Da de baja este móvil: deja de recibir avisos push (al cerrar sesión).
 */
export const meUnregisterPushDeviceBodyTokenRegExp = new RegExp('^Expo(?:nent)?PushToken\\[[A-Za-z0-9_-]{10,200}\\]$');


export const MeUnregisterPushDeviceBody = zod.object({
  "token": zod.string().regex(meUnregisterPushDeviceBodyTokenRegExp)
})

export const MeUnregisterPushDeviceResponse = zod.void()

